#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StageKind {
    Qrs,
    Beats,
    Af,
    Vf,
    SvRun,
}

impl StageKind {
    pub const ALL: [StageKind; 5] = [
        StageKind::Qrs,
        StageKind::Beats,
        StageKind::Af,
        StageKind::Vf,
        StageKind::SvRun,
    ];

    /// The name's prefix, and the key in a selection string.
    pub fn key(self) -> &'static str {
        match self {
            StageKind::Qrs => "qrs",
            StageKind::Beats => "beats",
            StageKind::Af => "af",
            StageKind::Vf => "vf",
            StageKind::SvRun => "svrun",
        }
    }
}

